let lang = 'en';
try { lang = localStorage.getItem('opensupport-language') || (navigator.language.startsWith('ru') ? 'ru' : 'en'); } catch {}
if (!copy[lang]) lang = 'en';
let projects = [], category = 'all', activeProject = null;
let session = null, apiReady = false, draft = {};
const t = key => copy[lang][key] || key;
const escape = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const heart = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
const linkIcon = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M8 11l4-4M6 8 4 10a3 3 0 0 0 4 4l2-2m0-4 2-2a3 3 0 0 1 4 4l-2 2"/></svg>';
const external = (url, label, cls = 'quiet-link') => `<a class="${cls}" href="${escape(safeURL(url))}" target="_blank" rel="noopener noreferrer">${escape(label)}</a>`;
function safeURL(value) {
 try { const u = new URL(value); return u.protocol === 'https:' && !u.username && !u.password && ['github.com','opencollective.com'].includes(u.hostname) ? u.href : '#'; } catch { return '#'; }
}
function fundingValid(value) {
 try { const u = new URL(value); return u.protocol === 'https:' && !u.port && !u.username && !u.password && !u.search && !u.hash && ((u.hostname === 'github.com' && /^\/sponsors\/[A-Za-z0-9][A-Za-z0-9_-]{0,99}\/?$/.test(u.pathname)) || (u.hostname === 'opencollective.com' && /^\/[A-Za-z0-9][A-Za-z0-9_-]{0,99}\/?$/.test(u.pathname))); } catch { return false; }
}
function translatedDOM() {
 document.documentElement.lang = lang;
 document.title = lang === 'ru' ? 'OpenSupport — Поддержите открытый код' : 'OpenSupport — Keep open source moving';
 $$('[data-t]').forEach(el => { const key = el.dataset.t; if (['headline','intro'].includes(key)) el.innerHTML = t(key); else el.textContent = t(key); });
 $$('[data-lang]').forEach(el => { el.classList.toggle('selected',el.dataset.lang === lang); el.setAttribute('aria-pressed',String(el.dataset.lang === lang)); });
 $('#search').placeholder = t('search'); $('#search').setAttribute('aria-label',t('search'));
 $('#provider').options[0].textContent = t('allPlatforms'); $('#provider').setAttribute('aria-label',t('allPlatforms'));
 $('#sort').options[0].textContent = t('curatedOrder'); $('#sort').options[1].textContent = t('az'); $('#sort').setAttribute('aria-label',t('curatedOrder'));
 $$('[data-close]').forEach(b => b.setAttribute('aria-label',t('close')));
 $('#wallet-copy-status').textContent = '';
 renderCategories(); renderCards(); renderArticles(); route();
 if (activeProject && $('#detail-dialog').open) renderDetail(activeProject);
}
function renderCategories() {
 const names = ['all',...new Set(projects.map(p=>p.category))];
 $('#categories').innerHTML = names.map(c => `<button class="chip ${category===c?'selected':''}" data-category="${escape(c)}" aria-pressed="${category===c}">${escape(t(c))}${c==='all'?`<span class="category-count">${projects.length}</span>`:''}</button>`).join('');
}
function filteredProjects() {
 const query = $('#search').value.trim().toLowerCase(), platform = $('#provider').value;
 let result = projects.filter(p => (category === 'all' || p.category===category) && (platform === 'all' || p.funding.some(f=>f.kind===platform)) && [p.name,p.repository,...Object.values(p.description),...(p.tags||[]),p.language,t(p.category)].join(' ').toLowerCase().includes(query));
 if ($('#sort').value === 'name') result.sort((a,b)=>a.name.localeCompare(b.name));
 return result;
}
function renderCards() {
 const list = filteredProjects();
 $('#result-total').textContent = list.length; $('#nav-count').textContent = projects.length;
 $('#project-grid').innerHTML = list.length ? list.map(p=>`<article class="project-card"><div class="card-top"><span class="project-symbol symbol-${escape(typeof p.id==='string'?p.id:'flask')}">${escape(p.symbol||p.name.substring(0,2))}</span><span class="funding-badge">${linkIcon}${escape(t(p.ownershipVerified?'verified':'publicFunding'))}</span></div><h3 class="project-title"><button data-detail="${escape(p.id)}">${escape(p.name)}</button></h3><div class="project-owner">${escape(p.repository)}</div><p class="project-description">${escape(p.description[lang])}</p><div class="tags">${(p.tags||[p.category,p.license]).map(tag=>`<span class="tag">${escape(tag)}</span>`).join('')}</div><div class="card-bottom"><span class="card-language"><span class="language-dot" aria-hidden="true"></span>${escape(p.language)}</span><button class="sponsor-link inline-btn" data-detail="${escape(p.id)}">${heart}${escape(t('sponsor'))}</button></div></article>`).join('') : `<div class="empty-state"><h3>${escape(t('none'))}</h3><p>${escape(t('noneText'))}</p><button class="secondary-btn" id="clear-filters">${escape(t('clear'))}</button></div>`;
}
function renderDetail(p) {
 activeProject = p;
 $('#detail-content').innerHTML = `<span class="project-symbol symbol-${escape(typeof p.id==='string'?p.id:'flask')}">${escape(p.symbol||p.name.substring(0,2))}</span><h2 class="detail-title">${escape(p.name)}</h2><div class="project-owner">${escape(p.repository)}</div><p class="detail-intro">${escape(p.description[lang])}</p><div class="tags"><span class="tag">${escape(p.language)}</span><span class="tag">${escape(t('license'))}: ${escape(p.license)}</span></div><div class="detail-links">${external('https://github.com/'+p.repository,t('repository'))}${external(p.fundingSource,t('source'))}</div><section class="detail-section"><h3>${escape(t('supportHeading'))}</h3><p>${escape(t('supportText'))}</p><div class="detail-links">${p.funding.map(f=>external(f.url,f.kind==='github'?'GitHub Sponsors':'Open Collective','primary-link')).join('')}</div></section><div class="disclosure">${escape(t(p.ownershipVerified?'verifiedNotice':'curatedNotice'))}</div>`;
}
function openDetail(id) { const p = projects.find(p=>String(p.id)===String(id)); if(!p) return; renderDetail(p); if(!$('#detail-dialog').open) $('#detail-dialog').showModal(); }
function renderArticles() {
 $('#how-page').innerHTML = `<div class="eyebrow"><span class="line"></span>${escape(t('how').toUpperCase())}</div><h1>${escape(t('howTitle'))}</h1><p class="lead">${escape(t('howIntro'))}</p><div class="article-grid">${[1,2,3,4].map(n=>`<article class="principle"><span class="number">0${n}</span><h2>${escape(t('how'+n))}</h2><p>${escape(t('how'+n+'Text'))}</p></article>`).join('')}</div><div class="disclosure">${escape(t('availability'))}</div>`;
 $('#principles-page').innerHTML = `<div class="eyebrow"><span class="line"></span>THE OPENSUPPORT MANIFESTO</div><h1>${t('manifestoTitle')}</h1><p class="lead">${escape(t('manifestoIntro'))}</p><div class="article-grid">${[1,2,3,4].map(n=>`<article class="principle"><span class="number">0${n}</span><h2>${escape(t('principle'+n))}</h2><p>${escape(t('principle'+n+'Text'))}</p></article>`).join('')}</div>`;
}
function route() {
 const requested = location.hash.slice(1), page = ['explore','how','principles'].includes(requested)?requested:'explore';
 $$('.page').forEach(p=>p.hidden=p.id!==page+'-page');
 $$('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#breadcrumb').textContent = t(page==='explore'?'directory':page);
}
function notify(text) { $('#toast').textContent=text; $('#toast').hidden=false; setTimeout(()=>$('#toast').hidden=true,3500); }
async function request(path, data) {
 const response = await fetch('/api/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json','X-CSRFToken':session?.csrfToken||''}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(15000)});
 if(!response.headers.get('content-type')?.includes('application/json')) throw new Error(t('backendDown'));
 const result=await response.json(); if(!response.ok)throw new Error(result.error||t('error')); return result;
}
async function loadSession() {
 try { const data=await request('session/'); if(!data.available)throw new Error(); session=data;apiReady=true; } catch { session=null;apiReady=false; }
}
function saveDraftFromForm() { const f=$('#project-form'); if(f)draft=Object.fromEntries(new FormData(f)); }
async function openSubmit() {
 $('#submit-content').innerHTML=`<p>${escape(t('checking'))}</p>`;
 if(!$('#submit-dialog').open)$('#submit-dialog').showModal();
 await loadSession(); renderSubmit();
}
function renderSubmit() {
 const authenticated=apiReady && session?.username;
 $('#submit-content').innerHTML=`<h2 class="detail-title">${escape(t('submissionTitle'))}</h2><p class="detail-intro">${escape(t('submissionIntro'))}</p><div class="steps"><span class="step active">${escape(t('stepProject'))}</span><span class="step">${escape(t('stepVerify'))}</span><span class="step">${escape(t('stepReview'))}</span></div>${!apiReady?`<div class="disclosure"><strong>${escape(t('offline'))}</strong><p>${escape(t('offlineText'))}</p></div>`:authenticated?`<div class="detail-links"><span>${escape(session.username)}</span><button class="inline-btn" id="logout">${escape(t('logout'))}</button><button class="inline-btn" id="my-submissions">${escape(t('mySubmissions'))}</button>${session.canReview?`<button class="inline-btn" id="moderation">${escape(t('reviewQueue'))}</button>`:''}</div>`:authForm()}
${!apiReady||authenticated?projectForm():''}`;
 bindSubmit();
}
function authForm() {
 return `<p>${escape(t('needAccount'))}</p><form id="auth-form"><div class="form-row"><label for="username">${escape(t('username'))}</label><input id="username" name="username" autocomplete="username" maxlength="150" required></div><div class="form-row"><label for="password">${escape(t('password'))}</label><input id="password" name="password" type="password" autocomplete="current-password" maxlength="128" required><span class="form-hint">${escape(t('passwordHint'))}</span></div><p class="form-error" id="auth-error" role="alert"></p><div class="form-actions"><button class="primary-link" value="login">${escape(t('login'))}</button>${session?.signupEnabled?`<button class="secondary-btn" value="register">${escape(t('register'))}</button>`:''}</div></form>`;
}
function projectForm() {
 const field=(key,label,placeholder='',max=200)=>`<div class="form-row"><label for="field-${key}">${escape(t(label))}</label><input id="field-${key}" name="${key}" value="${escape(draft[key]||'')}" placeholder="${escape(placeholder)}" maxlength="${max}" required></div>`;
 return `<form id="project-form">${field('repository','repoLabel','https://github.com/owner/project',140)}${field('title','titleLabel','',80)}${['en','ru'].map(l=>`<div class="form-row"><label for="desc-${l}">${escape(t(l==='en'?'englishDescription':'russianDescription'))}</label><textarea id="desc-${l}" name="description_${l}" maxlength="400" required>${escape(draft['description_'+l]||'')}</textarea></div>`).join('')}<div class="form-row"><label for="field-category">${escape(t('category'))}</label><select name="category" id="field-category">${['frameworks','testing','networking','data','tooling'].map(c=>`<option value="${c}" ${draft.category===c?'selected':''}>${escape(t(c))}</option>`).join('')}</select></div>${field('funding_url','fundingLabel','https://github.com/sponsors/username',220)}<p class="form-hint">${escape(t('fundingHint'))}</p><label class="check-label"><input type="checkbox" required>${escape(t('consent'))}</label><p id="submit-error" class="form-error" role="alert"></p><div class="form-actions"><button class="primary-link">${escape(t(apiReady?'send':'download'))}</button></div></form>`;
}
function bindSubmit() {
 $('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const result=await request(b.value+'/',Object.fromEntries(new FormData(e.target)));session={...session,...result};await loadSession();renderSubmit();}catch(err){$('#auth-error').textContent=err.message;}finally{b.disabled=false;}});
 $('#logout')?.addEventListener('click',async()=>{try{await request('logout/',{});await loadSession();renderSubmit();}catch(err){notify(err.message);}});
 $('#my-submissions')?.addEventListener('click',()=>loadSubmissions(false));
 $('#moderation')?.addEventListener('click',()=>loadSubmissions(true));
 $('#project-form')?.addEventListener('submit',async e=>{
 e.preventDefault();saveDraftFromForm();const error=$('#submit-error');error.textContent='';
 if(!/^https:\/\/github\.com\/[A-Za-z0-9][A-Za-z0-9-]{0,38}\/[A-Za-z0-9_.-]{1,100}\/?$/.test(draft.repository)||['.','..'].includes(draft.repository.replace(/\/$/,'').split('/').pop())){error.textContent=t('invalidRepo');return;}
 if(!fundingValid(draft.funding_url)){error.textContent=t('invalidFunding');return;}
 if(!apiReady){const blob=new Blob([JSON.stringify({format:'opensupport-draft-v1',...draft},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='opensupport-project-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(t('draftSaved'));return;}
 const b=e.submitter;b.disabled=true;try{const result=await request('submissions/',draft);draft={};showProof(result);}catch(err){error.textContent=err.message;}finally{b.disabled=false;}
 });
}
function showProof(data) {
 const content=JSON.stringify(data.proof,null,2);
 $('#submit-content').innerHTML=`<h2>${escape(t('proofTitle'))}</h2><p class="detail-intro">${escape(t('proofText'))}</p><pre class="code-block">${escape(content)}</pre><div class="form-actions"><button class="secondary-btn" id="copy-proof">${escape(t('copyCode'))}</button><button class="primary-link" id="verify-proof">${escape(t('verify'))}</button></div><p class="form-error" id="proof-error" role="alert"></p>`;
 $('#copy-proof').onclick=async()=>{try{await navigator.clipboard.writeText(content);notify(t('copied'));}catch{$('.code-block').setAttribute('tabindex','0');$('.code-block').focus();}};
 $('#verify-proof').onclick=async e=>{e.target.disabled=true;try{await request(`submissions/${data.id}/verify/`,{});notify(t('reviewSuccess'));await loadSubmissions(false);}catch(err){$('#proof-error').textContent=err.message;}finally{e.target.disabled=false;}};
}
async function loadSubmissions(moderation) {
 try{
 const {submissions}=await request(moderation?'moderation/':'submissions/mine/');
 $('#submit-content').innerHTML=`<h2>${escape(t(moderation?'reviewQueue':'mySubmissions'))}</h2><button class="inline-btn" id="back-submit">${escape(t('submitProject'))}</button>${!submissions.length?`<p>${escape(t('noSubmissions'))}</p>`:submissions.map(s=>`<section class="detail-section"><h3>${escape(s.name)}</h3>${external('https://github.com/'+s.repository,s.repository)}<p>${escape(s.description[lang])}</p>${s.funding.map(f=>external(f.url,f.url)).join('')}<p>${escape(t(s.status))}</p>${s.reviewNote?`<p>${escape(s.reviewNote)}</p>`:''}${!moderation&&s.status==='unverified'?`<button class="secondary-btn" data-renew="${s.id}">${escape(t('renew'))}</button>`:''}${moderation?`<div class="form-row"><label for="note-${s.id}">${escape(t('reviewNote'))}</label><textarea id="note-${s.id}" maxlength="500" required></textarea></div><div class="form-actions"><button class="primary-link" data-review="approve" data-id="${s.id}">${escape(t('approve'))}</button><button class="secondary-btn" data-review="reject" data-id="${s.id}">${escape(t('reject'))}</button></div>`:''}</section>`).join('')}<p id="list-error" class="form-error" role="alert"></p>`;
 $('#back-submit').onclick=renderSubmit;
 $$('[data-renew]').forEach(b=>b.onclick=async()=>{try{showProof(await request(`submissions/${b.dataset.renew}/challenge/`,{}));}catch(err){$('#list-error').textContent=err.message;}});
 $$('[data-review]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const note=$('#note-'+b.dataset.id).value;if(!note.trim())throw new Error(t('reviewNote'));await request(`submissions/${b.dataset.id}/review/`,{decision:b.dataset.review,note});notify(t('reviewed'));await loadSubmissions(true);await loadProjects();}catch(err){$('#list-error').textContent=err.message;}finally{b.disabled=false;}});
 }catch(err){notify(err.message);}
}
async function loadProjects() {
 try { const response=await fetch('/projects.json');if(!response.ok)throw new Error();projects=await response.json(); } catch { $('#project-grid').innerHTML=`<div class="empty-state"><p>${escape(t('error'))}</p></div>`;return; }
 try { const data=await request('projects/'); const approved=data.projects||[]; const index=new Map(projects.map(p=>[p.repository.toLowerCase(),p]));for(const p of approved)index.set(p.repository.toLowerCase(),p);projects=[...index.values()]; }catch{}
 renderCategories();renderCards();
}
$$('[data-lang]').forEach(button=>button.addEventListener('click',()=>{saveDraftFromForm();lang=button.dataset.lang;try{localStorage.setItem('opensupport-language',lang);}catch{}translatedDOM();if($('#submit-dialog').open)renderSubmit();}));
$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;renderCategories();renderCards();}});
$('#search').addEventListener('input',renderCards);$('#provider').addEventListener('change',renderCards);$('#sort').addEventListener('change',renderCards);
$('#project-grid').addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b)openDetail(b.dataset.detail);if(e.target.id==='clear-filters'){category='all';$('#search').value='';$('#provider').value='all';renderCategories();renderCards();}});
$('#add-project').onclick=openSubmit;$('#add-project-bottom').onclick=openSubmit;
$$('[data-close]').forEach(b=>b.onclick=()=>{saveDraftFromForm();document.getElementById(b.dataset.close).close();});
window.addEventListener('hashchange',()=>{route();window.scrollTo({top:0});});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();location.hash='explore';$('#search').focus();}});
translatedDOM();loadProjects();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 try{Promise.resolve(document.modelContext.registerTool({name:'filter_open_source_projects',title:'Filter open source projects',description:'Set the visible catalogue search and return matching projects. Does not submit applications or make payments.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>100||Object.keys(input).some(k=>k!=='query'))throw new Error('Expected a query of at most 100 characters.');location.hash='explore';$('#search').value=input.query;category='all';$('#provider').value='all';renderCategories();renderCards();return {projects:filteredProjects().map(p=>({name:p.name,repository:p.repository}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

$('#open-support').addEventListener('click', () => {
 const reduceMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 $('#support-project-section').scrollIntoView({behavior: reduceMotion ? 'auto' : 'smooth', block: 'start'});
 $('#platform-support-title').focus({preventScroll: true});
});
$('#copy-wallet').addEventListener('click', async () => {
 const wallet = $('#support-wallet');
 const status = $('#wallet-copy-status');
 try {
  if (!navigator.clipboard?.writeText) throw new Error('Clipboard unavailable');
  await navigator.clipboard.writeText(wallet.value);
  status.textContent = t('walletCopied');
 } catch {
  wallet.focus();
  wallet.select();
  wallet.setSelectionRange(0, wallet.value.length);
  status.textContent = t('walletCopyFallback');
 }
});
